using Microsoft.Data.Sqlite;
using Microsoft.AspNetCore.Identity;
namespace Academic;
public class Store:IStore {
 readonly string cs; readonly PasswordHasher<string> hasher=new();
 public Store(string path){cs=new SqliteConnectionStringBuilder{DataSource=path,ForeignKeys=true,DefaultTimeout=15}.ToString();using var c=Open();using var q=Cmd(c,null,"CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,hash TEXT NOT NULL,role TEXT NOT NULL); CREATE TABLE IF NOT EXISTS spaces(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,type TEXT NOT NULL); CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),space_id INTEGER REFERENCES spaces(id),start INTEGER NOT NULL,end INTEGER NOT NULL,status TEXT NOT NULL); CREATE INDEX IF NOT EXISTS ix_res ON reservations(space_id,start,end,status);");q.ExecuteNonQuery();}
 SqliteConnection Open(){var c=new SqliteConnection(cs);c.Open();return c;}
 static SqliteCommand Cmd(SqliteConnection c,SqliteTransaction? t,string sql,params object[] args){var q=c.CreateCommand();q.Transaction=t;q.CommandText=sql;for(int i=0;i<args.Length;i++)q.Parameters.AddWithValue("@p"+i,args[i]);return q;}
 static long Insert(SqliteConnection c,SqliteTransaction? t,string sql,params object[] args){using var q=Cmd(c,t,sql+"; SELECT last_insert_rowid();",args);return (long)q.ExecuteScalar()!;}
 static User ReadUser(SqliteDataReader r)=>new(r.GetInt64(0),r.GetString(1),r.GetString(2));
 public User Register(Credentials x,string role="requester"){var email=x.Email?.Trim().ToLowerInvariant()??"";if(!email.Contains('@')||x.Password is null||x.Password.Length<8)throw new RuleException("Correo o contraseña inválidos");using var c=Open();try{return new(Insert(c,null,"INSERT INTO users(email,hash,role) VALUES(@p0,@p1,@p2)",email,hasher.HashPassword(email,x.Password),role),email,role);}catch(SqliteException e)when(e.SqliteErrorCode==19){throw new RuleException("Correo duplicado");}}
 public User? Login(Credentials x){using var c=Open();using var q=Cmd(c,null,"SELECT id,email,role,hash FROM users WHERE email=@p0",x.Email.Trim().ToLowerInvariant());using var r=q.ExecuteReader();if(!r.Read()||hasher.VerifyHashedPassword(r.GetString(1),r.GetString(3),x.Password)==PasswordVerificationResult.Failed)return null;return ReadUser(r);}
 public User? GetUser(long id){using var c=Open();using var q=Cmd(c,null,"SELECT id,email,role FROM users WHERE id=@p0",id);using var r=q.ExecuteReader();return r.Read()?ReadUser(r):null;}
 public List<User> Users(){using var c=Open();using var q=Cmd(c,null,"SELECT id,email,role FROM users");using var r=q.ExecuteReader();List<User> a=[];while(r.Read())a.Add(ReadUser(r));return a;}
 public void Role(long id,string role){if(role is not ("admin" or "requester"))throw new RuleException("Rol inválido");using var c=Open();using var q=Cmd(c,null,"UPDATE users SET role=@p0 WHERE id=@p1",role,id);if(q.ExecuteNonQuery()==0)throw new RuleException("Usuario inexistente");}
 public List<Space> Spaces(){using var c=Open();using var q=Cmd(c,null,"SELECT id,name,type FROM spaces");using var r=q.ExecuteReader();List<Space> a=[];while(r.Read())a.Add(new(r.GetInt64(0),r.GetString(1),r.GetString(2)));return a;}
 public long SaveSpace(SpaceInput x,long? id=null){if(string.IsNullOrWhiteSpace(x.Name)||x.Type is not ("laboratorio" or "auditorio" or "computo"))throw new RuleException("Espacio inválido");using var c=Open();try{if(id is null)return Insert(c,null,"INSERT INTO spaces(name,type) VALUES(@p0,@p1)",x.Name.Trim(),x.Type);using var q=Cmd(c,null,"UPDATE spaces SET name=@p0,type=@p1 WHERE id=@p2",x.Name.Trim(),x.Type,id.Value);if(q.ExecuteNonQuery()==0)throw new RuleException("Espacio inexistente");return id.Value;}catch(SqliteException e)when(e.SqliteErrorCode==19){throw new RuleException("Nombre duplicado");}}
 static bool Free(SqliteConnection c,SqliteTransaction? t,Booking b){using var exists=Cmd(c,t,"SELECT COUNT(*) FROM spaces WHERE id=@p0",b.SpaceId);if((long)exists.ExecuteScalar()! ==0)throw new RuleException("Espacio inexistente");using var q=Cmd(c,t,"SELECT COUNT(*) FROM reservations WHERE space_id=@p0 AND status IN ('pending','approved') AND start<@p1 AND end>@p2",b.SpaceId,b.End.UtcTicks,b.Start.UtcTicks);return (long)q.ExecuteScalar()! ==0;}
 public bool Available(Booking b){Rules.Interval(b.Start,b.End);using var c=Open();return Free(c,null,b);}
 static void Limit(SqliteConnection c,SqliteTransaction t,long user,Booking b){long lo=b.Start.UtcTicks,hi=b.End.UtcTicks;using var q=Cmd(c,t,"SELECT start,end FROM reservations WHERE user_id=@p0 AND space_id=@p1 AND status IN ('pending','approved')",user,b.SpaceId);using var r=q.ExecuteReader();List<(long Start,long End)> ranges=[];while(r.Read())ranges.Add((r.GetInt64(0),r.GetInt64(1)));bool changed;do{changed=false;foreach(var x in ranges){if(x.Start<=hi&&x.End>=lo){long l=Math.Min(lo,x.Start),h=Math.Max(hi,x.End);if(l!=lo||h!=hi){lo=l;hi=h;changed=true;}}}}while(changed);if(hi-lo>TimeSpan.FromHours(4).Ticks)throw new RuleException("Máximo cuatro horas consecutivas");}
 public long Reserve(long user,Booking b){Rules.Interval(b.Start,b.End);using var c=Open();using var t=c.BeginTransaction(deferred:false);if(!Free(c,t,b))throw new RuleException("Horario ocupado");Limit(c,t,user,b);var id=Insert(c,t,"INSERT INTO reservations(user_id,space_id,start,end,status) VALUES(@p0,@p1,@p2,@p3,'pending')",user,b.SpaceId,b.Start.UtcTicks,b.End.UtcTicks);t.Commit();return id;}
 public List<Reservation> History(long? user){using var c=Open();using var q=user is null?Cmd(c,null,"SELECT * FROM reservations ORDER BY id"):Cmd(c,null,"SELECT * FROM reservations WHERE user_id=@p0 ORDER BY id",user.Value);using var r=q.ExecuteReader();List<Reservation> a=[];while(r.Read())a.Add(new(r.GetInt64(0),r.GetInt64(1),r.GetInt64(2),new DateTimeOffset(r.GetInt64(3),TimeSpan.Zero),new DateTimeOffset(r.GetInt64(4),TimeSpan.Zero),r.GetString(5)));return a;}
 public void Change(long id,User actor,string status){using var c=Open();using var t=c.BeginTransaction(deferred:false);long owner;string old;using(var q=Cmd(c,t,"SELECT user_id,status FROM reservations WHERE id=@p0",id))using(var r=q.ExecuteReader()){if(!r.Read())throw new RuleException("Reserva inexistente");owner=r.GetInt64(0);old=r.GetString(1);}if(actor.Role!="admin"&&(actor.Id!=owner||status!="cancelled"))throw new UnauthorizedAccessException();Rules.Transition(old,status);using var update=Cmd(c,t,"UPDATE reservations SET status=@p0 WHERE id=@p1",status,id);update.ExecuteNonQuery();t.Commit();}
}
